// in: add; out: take away (never below 0); lookup: say what is there
const stock = flow.get('stock') || {};
const d = msg.data, code = (d.code || d.lookup || {}).code;
const item = stock[code] || { qty: 0, place: '', lent: '' };
const qty = typeof d.qty === 'number' ? d.qty : 1;
let say;
if (msg.tile === 'checkin') {
  item.qty += qty; if (d.place) item.place = d.place; item.lent = '';
  say = { en: '+' + qty + ' → ' + item.qty, fr: '+' + qty + ' → ' + item.qty, de: '+' + qty + ' → ' + item.qty };
} else if (msg.tile === 'checkout') {
  item.qty = Math.max(0, item.qty - qty); if (d.who) item.lent = d.who;
  say = { en: '−' + qty + ' → ' + item.qty + (item.qty ? '' : ' (none left)'), fr: '−' + qty + ' → ' + item.qty + (item.qty ? '' : ' (plus aucun)'),
          de: '−' + qty + ' → ' + item.qty + (item.qty ? '' : ' (keine mehr)') };
} else {
  say = item.qty ? { en: item.qty + ' in ' + (item.place || '?'), fr: item.qty + ' en ' + (item.place || '?'), de: item.qty + ' in ' + (item.place || '?') }
                 : { en: 'Not in stock', fr: 'Pas en stock', de: 'Nicht im Bestand' };
  if (item.lent) say = { en: 'Lent to ' + item.lent, fr: 'Prêté à ' + item.lent, de: 'Verliehen an ' + item.lent };
}
if (msg.tile !== 'lookup') stock[code] = item;
flow.set('stock', stock);
const total = Object.values(stock).reduce((n, x) => n + x.qty, 0);
return [{ payload: say }, { payload: total, tile: 'stock' }, { payload: { code, item, tile: msg.tile, data: d } }];
